export const MAPA_PROVEEDOR_POR_RFC: Record<string, ProveedorCatalogoItem> = Object.fromEntries(
  CATALOGO_PROVEEDORES.map((item) => [item.rfc.toUpperCase(), item])
);

export function obtenerDatosCatalogoPorRfc(rfc?: string | null): ProveedorCatalogoItem | null {
  if (!rfc) return null;
  return MAPA_PROVEEDOR_POR_RFC[rfc.trim().toUpperCase()] || null;
}

export function resolverCodigoProveedor(rfc?: string | null, codigoActual?: string | null): string {
  const limpio = (codigoActual || '').trim();
  if (limpio && !limpio.startsWith('PRV-') && limpio !== 'S/N') {
    return limpio;
  }
  const delCatalogo = obtenerDatosCatalogoPorRfc(rfc)?.codigoProveedor;
  if (delCatalogo) {
    return delCatalogo;
  }
  return limpio || 'S/N';
}

export function resolverDiasCreditoProveedor(rfc?: string | null, diasActuales?: number | null): number | null {
  if (diasActuales !== undefined && diasActuales !== null && Number(diasActuales) >= 0) {
    return Number(diasActuales);
  }
  const delCatalogo = obtenerDatosCatalogoPorRfc(rfc);
  if (delCatalogo && delCatalogo.diasCredito !== undefined && delCatalogo.diasCredito !== null) {
    return Number(delCatalogo.diasCredito);
  }
  return null;
}
